def solution(input_str):
    l, r = map(int, input_str.strip().split())

    if l > r:
        return '0\n'

    # Sieve of Eratosthenes to mark primes
    n = r
    is_prime = bytearray([1]) * (n + 1)
    is_prime[0] = 0
    is_prime[1] = 0

    sqrt_n = int(n ** 0.5) + 1
    for i in range(2, sqrt_n):
        if is_prime[i]:
            is_prime[i*i:n+1:i] = bytearray([0]) * ((n - i*i) // i + 1)

    count = 0
    for i in range(l, r + 1):
        if is_prime[i]:
            if i == 2 or i % 4 == 1:
                count += 1

    return str(count) + '\n'
