import sys

def rev(n):
    """Reverse a positive integer, removing leading zeros"""
    return int(str(n)[::-1])

def solve():
    """Main solver function, reads from stdin"""
    try:
        line = sys.stdin.read().strip()
        if not line:
            return "-1"
        parts = list(map(int, line.split()))
        maxx, maxy, w = parts

        # If w is very large and cannot be satisfied
        max_possible = 0
        # We'll search for the best (x, y) pair
        best_x, best_y = -1, -1
        best_count = 0

        # Precompute counts for numbers 1 to max(maxx, maxy)
        limit = max(maxx, maxy)

        # Group numbers by signature: a / rev(a) = b / rev(b)
        # Use a dictionary to store (numerator, denominator) pairs
        signature_groups = {}

        def get_signature(a):
            ra = rev(a)
            if ra == 0:
                return -1  # Shouldn't happen for a >= 1
            # Create a canonical pair
            g = (a, ra)
            return g

        # Store counts for each signature
        sig_counts = {}

        for i in range(1, limit + 1):
            ra = rev(i)
            if ra == 0:
                continue
            signature = get_signature(i)
            sig_counts[signature] = sig_counts.get(signature, 0) + 1

        # For pairs with same signature, they form lucky tickets
        # If we have a signature with count c, we get c*c pairs

        # Precompute cumulative by signature
        sig_count = 0
        # Sort signatures to process them
        sorted_sigs = sorted(sig_counts.items())

        # Try different x values from 1 to maxx
        for x in range(1, maxx + 1):
            # Calculate signatures present in [1, x]
            x_sigs = {}
            for i in range(1, x + 1):
                ra = rev(i)
                if ra == 0:
                    continue
                signature = get_signature(i)
                x_sigs[signature] = x_sigs.get(signature, 0) + 1

            # Try different y values from 1 to maxy
            for y in range(1, maxy + 1):
                # Calculate signatures present in [1, y]
                y_sigs = {}
                for j in range(1, y + 1):
                    ra = rev(j)
                    if ra == 0:
                        continue
                    signature = get_signature(j)
                    y_sigs[signature] = y_sigs.get(signature, 0) + 1

                # Count lucky tickets: sum over all common signatures c_x * c_y * count_of_pairs_with_same_sig
                lucky_count = 0
                for sig in x_sigs:
                    if sig in y_sigs:
                        count_x = x_sigs[sig]
                        count_y = y_sigs[sig]
                        lucky_count += count_x * count_y

                if lucky_count >= w:
                    if best_x == -1 or x * y < best_x * best_y:
                        best_x, best_y = x, y
                        best_count = lucky_count

            if best_x != -1:
                break  # If we found any solution, try to minimize x*y further

        if best_x == -1:
            return "-1"
        return f"{best_x} {best_y}"

    except Exception:
        return "-1"

def solution(input_str):
    """Solve the problem given input as string"""
    if not input_str.strip():
        return "-1"
    result = solve()
    return result
