                    if di == 0 and dj == 0:
                        continue
                    ni, nj = i + di, j + dj
                    if 0 <= ni < n and 0 <= nj < m:
                        if work[ni][nj] == c:
                            return "0"

    # Try pattern-based coloring with 4 groups
    from itertools import permutations

    for perm in permutations([1, 2, 3, 4]):
        # cmap[(i%2)[j%2]] = perm[...], mapped as grid[i%2][j%2]
        cmap = [[perm[0], perm[1]], [perm[2], perm[3]]]

        # Check consistency
        consistent = True
        for i in range(n):
            for j in range(m):
                if work[i][j] != 0:
                    if cmap[i % 2][j % 2] != work[i][j]:
