Looking at this problem, I need to find minimal k-coverings for a bipartite graph. A k-covering requires every vertex to have at least degree k using the selected edges, and I need to minimize the number of edges used.

Let me analyze the input/output pattern:
- For each k from 1 to minDegree, output the number of edges and their indices
- The indices should be sorted
- If k=1 requires 0 edges (e.g., isolated vertices), output "0"

For finding minimal k-coverings in bipartite graphs, I'll use a flow-based approach:
1. Build a flow network where:
   - Source → left vertices U with capacity k
   - Left vertices U → right vertices V (for each original edge) with capacity 1  
   - Right vertices V → sink with capacity k
2. Find which U→V edges carry flow (these are the selected edges)
3. Output the indices of selected edges

```python
from collections import deque
import sys

class Dinic:
    def __init__(self, n):
        self.n = n
        self.graph = [[] for _ in range(n)]
        self.level = []

    def add_edge(self, u, v, capacity, edge_index=-1):
        self.graph[u].append([v, capacity, len(self.graph[v]), edge_index])
        self.graph[v].append([u, 0, len(self.graph[u]) - 1, -1])

    def bfs(self, s, t):
        self.level = [-1] * self.n
        self.level[s] = 0
        queue = deque([s])
        while queue:
            u = queue.popleft()
            for v, cap, rev, _ in self.graph[u]:
                if cap > 0 and self.level[v] < 0:
                    self.level[v] = self.level[u] + 1
                    queue.append(v)
        return self.level[t] >= 0

    def dfs(self, u, t, flow, ptr):
        if u == t or flow == 0:
            return flow
        for i in range(ptr[u], len(self.graph[u])):
            ptr[u] = i
            v, cap, rev, edge_idx = self.graph[u][i]
            if self.level[v] == self.level[u] + 1 and cap > 0:
                pushed = self.dfs(v, t, min(flow, cap), ptr)
                if pushed > 0:
                    self.graph[u][i][1] -= pushed
                    self.graph[v][rev][1] += pushed
                    return pushed
        return 0

    def max_flow(self, s, t, track_flows=None):
        if track_flows is None:
            track_flows = set()
        max_f = 0
        while self.bfs(s, t):
            ptr = [0] * self.n
            path_edges = []
            while True:
                pushed = self.dfs(s, t, float('inf'), ptr)
                if pushed == 0:
                    break
                max_f += pushed
                if max_f >= pushed * 100:  # Limit iterations
                    break
        # Find edges that carried flow (forward edges with capacity decreased)
        for u in range(self.n):
            for i, (v, cap, rev, edge_idx) in enumerate(self.graph[u]):
                if edge_idx > -1 and cap == 0:
                    track_flows.add(edge_idx)
        return max_f

def solution(input_str):
    lines = input_str.strip().split('\n')
    n1, n2, m = map(int, lines[0].split())

    edges = []
    for i in range(m):
        parts = lines[1 + i].split()
        if len(parts) < 2:
            continue
        u, v = int(parts[0]), int(parts[1])
        edges.append((u - 1, v - 1, i + 1))  # 0-indexed vertices, 1-indexed edge

    # Count degrees for left vertices
    deg = [0] * n1
    for u, v, _ in edges:
        deg[u] += 1

    if n1 > 0:
        min_k = min(deg)
    else:
        min_k = 0

    output_lines = []

    for k in range(1, min_k + 1):
        dinic = Dinic(n1 + n2 + 2)
        S = n1 + n2 + 1
        T = n1 + n2 + 2

        # Source to left vertices with capacity k
        for i in range(n1):
            dinic.add_edge(S, i, k)

        # Left to right for each original edge (capacity 1)
        for u, v, idx in edges:
            if u >= 0 and v >= 0:
                dinic.add_edge(u, v + n1, 1, idx)

        # Right vertices to sink with capacity k
        for i in range(n2):
            dinic.add_edge(i + n1, T, k)

        selected = set()
        dinic.max_flow(S, T, selected)

        result = sorted(list(selected))
        output_lines.append(f"{len(result)} {' '.join(map(str, result))}")

    return '\n'.join(output_lines)
