```python
def solution(input_str):
    lines = input_str.strip().split('\n')
    n, m = map(int, lines[0].split())

    edges = []
    for i in range(1, m + 1):
        if i < len(lines):
            u, v = map(int, lines[i].split())
            edges.append((u - 1, v - 1))

    # Read parities
    parity_line_idx = m + 1
    parities = []
    while len(parities) < n and parity_line_idx < len(lines):
        line = lines[parity_line_idx].strip()
        if line:
            parities.extend(map(int, line.split()))
            parity_line_idx += 1

    if len(parities) < n:
        parities.extend([0] * (n - len(parities)))
    parities = parities[:n]

    # Build adjacency list
    adj = [[] for _ in range(n)]
    for u, v in edges:
        adj[u].append(v)
        adj[v].append(u)

    # All even parities: empty path
    if all(p == 0 for p in parities):
        return '0\n'

    # Build path using DFS
    path = [0]

    def dfs(u, start_node, depth):
        path[-1] = u

        # Check if path is valid with current length
        if depth >= 4 * n and all_check():
            return True

        if depth >= 4 * n:
            return False

        for v in adj[u]:
            if dfs(v, start_node, depth + 1) and all_check():
                return True

        return False

    def all_check():
        # Check if requirements are satisfied
        for i in range(n):
            count = path.count(i)
            if parities[i] == 1 and count % 2 == 0:
                return False
            if parities[i] == 0 and count % 2 == 1:
                return False
        return True

    # Try starting from each odd-parity vertex
    for start in range(n):
        if parities[start] == 1:
            path = [start]
            if dfs(start, start, 1):
                final_path = path[:-1] if len(path) > 1 and all_check() else path

                # Validate
                if all_check():
                    return f'{len(final_path)}\n' + ' '.join(map(str, [x + 1 for x in final_path]))

    # Return -1 if no valid path found
    return '-1\n'

