```python
import math
from functools import reduce

def gcd(a, b):
    while b:
        a, b = b, a % b
    return a

def coprime_with(x, seq):
    """Check if x is coprime with all elements in seq"""
    for val in seq:
        if gcd(x, val) > 1:
            return False
    return True

def find_coprime_number(x, seq, small_primes):
    """Find minimum number >= 1 that is coprime with all in seq using available small primes"""
    if coprime_with(x, seq):
        return x

    for prime in small_primes:
        if coprime_with(prime, seq):
            return prime
        # Try composite of two primes
        for p2 in small_primes:
            if p2 == prime:
                continue
            candidate = prime * p2
            if coprime_with(candidate, seq):
                return min(candidate, find_coprime_number(prime, seq, small_primes))

