def solution(input_str):
    lines = input_str.strip().split('\n')
    N = int(lines[0])

    # Parse costs into N x N matrix
    cost = [[0] * N for _ in range(N)]
    for i in range(N):
        row = list(map(int, lines[1 + i].split()))
        j = 0
        for k in range(N):
            if k != i:
                cost[i][k] = row[j]
                j += 1

    # Build preference list for each city (sorted by cost, lower is better)
    pref = [[] for _ in range(N)]
    for i in range(N):
        indexed = [(j, cost[i][j]) for j in range(N) if j != i]
        indexed.sort(key=lambda x: x[1])
        pref[i] = [j for j, _ in indexed]

    # Build preference rank map: pref_rank[i][j] = rank (smaller = better)
    pref_rank = [[0] * N for _ in range(N)]
    for i in range(N):
        for rank, j in enumerate(pref[i]):
            pref_rank[i][j] = rank

    # Gale-Shapley algorithm for Stable Roommates
    matched = [-1] * N  # matched[i] = partner of i, -1 if unmatched
    next_proposal = [0] * N

    bool changed = True
    while changed:
        changed = False
        # In each phase, try to match all free cities
        for i in range(N):
            if matched[i] == -1:
                # Find next city to propose to
                if next_proposal[i] < N - 1:
                    v = pref[i][next_proposal[i]]
                    next_proposal[i] += 1

                    if matched[v] == -1:
                        # v is free, accept proposal
                        matched[i] = v
                        matched[v] = i
                        changed = True
                    else:
                        # v is already matched with w
                        w = matched[v]
                        # v accepts i if i is better ranked
                        if pref_rank[v][i] < pref_rank[v][w]:
                            # v switches to i, w becomes free
                            matched[v] = i
                            matched[i] = v
                            matched[w] = -1
                            changed = True

    # Build quick lookup: who matches with whom
    partner = {}
    for i in range(N):
        if matched[i] != -1:
            partner[i] = matched[i]

    # Check stability: no two cities should mutually prefer each other
    # over their current partners (or being unmatched)
    valid = True
    for i in range(N):
        if matched[i] != -1:
            current = matched[i]

            # Check all cities j that i prefers over current partner
            rank_curr = pref_rank[i][current]
            for j in pref[i]:
                if pref_rank[i][j] >= rank_curr:
                    # j is not better for i
                    break

                # Check if j is matched to someone
                j_partner = partner.get(j, -1)
                if j_partner != -1:
                    # Check if j would reject i (j prefers current match over i)
                    rank_j = pref_rank[j][i]
                    rank_j_partner = pref_rank[j][j_partner]
                    if rank_j < rank_j_partner:
                        # j prefers their current match, so no blocking pair
                        pass
                    else:
                        # j prefers i over current match - this is a blocking pair
                        valid = False
                        break

    if not valid:
        return '-1\n'

    # Output result: city matched with + 1 (1-indexed), or -1 if unmatched
    result = []
    for i in range(N):
        if matched[i] != -1:
            result.append(str(matched[i] + 1))
        else:
            result.append('-1')

    return '\n'.join(result) + '\n'
