def solution(input_str):
    import sys
    from collections import defaultdict

    lines = input_str.strip().split('\n')
    n, m = map(int, lines[0].split())

    edges = []
    for i in range(1, m + 1):
        a, b = map(int, lines[i].split())
        if a > b:
            a, b = b, a
        edges.append((a, b, i))

    def cross(a, b, c, d):
        # Check if edge (a,b) crosses edge (c,d)
        # Crosses if endpoints are interleaved
        return (a < c < b < d) or (c < a < d < b)

    # Build conflict graph
    conflict = defaultdict(set)
    for i in range(m):
        for j in range(i + 1, m):
            a1, b1 = edges[i][0], edges[i][1]
            a2, b2 = edges[j][0], edges[j][1]
            if cross(a1, b1, a2, b2):
                conflict[i].add(j)
                conflict[j].add(i)

    # Try to find valid assignment using 2-SAT or bipartite checking
    # This graph must be bipartite for a solution to exist

    visited = [False] * m
    color = [-1] * m
    possible = True

    for i in range(m):
        if visited[i]:
            continue
        color[i] = 0
        queue = [i]
        while queue:
            u = queue.pop(0)
            for v in conflict[u]:
                if color[v] == -1:
                    color[v] = 1 - color[u]
                    visited[v] = True
                    queue.append(v)
                elif color[v] == color[u]:
                    return "Impossible"

    # Construct the result
    result = []
    for i in range(m):
        if color[i] == 0:
            result.append('i')
        else:
            result.append('o')

    return ''.join(result) + '\n'
