def solution(input_str):
    lines = input_str.strip().split('\n')
    s1, s2, virus = lines[0], lines[1], lines[2]
    m, n, v = len(s1), len(s2), len(virus)

    # Edge cases
    if m == 0 or n == 0:
        return "0"
    if v == 0:
        # No virus constraint
