    pi = [0] * v
    for i in range(1, v):
        j = pi[i - 1]
        while j > 0 and virus[i] != virus[j]:
            j = pi[j - 1]
        if virus[i] == virus[j]:
            j += 1
        pi[i] = j

    # Build KMP transition table:
    # transition[k][char_code] = next state after processing character
    transition = [[0] * 26 for _ in range(v)]
    for k in range(v):
        for code in range(26):
            char = chr(ord('A') + code)
            state = k
            while state > 0 and virus[state] != char:
                state = pi[state - 1]
            if virus[state] == char:
                state += 1
            if state < v:
                transition[k][code] = state

    # DP state: dp[i][j][k] = max length of valid common subsequence
    # using s1[:i], s2[:j], ending with virus match state k
