                    return True  # Force opponent to lose
                if mv == e:
                    continue
                if can_win(mv) is False:
                    return True  # Can force opponent into losing position

            return False

        return can_win(s)

    lines = input_str.strip().split('\n')
    t = int(lines[0])
    queries = []

    for i in range(1, t + 1):
        if i < len(lines):
            parts = lines[i].split()
            if len(parts) >= 2:
                queries.append((int(parts[0]), int(parts[1])))

    lees_can_win_all = True
    lees_can_lose_all = True

    for i, (s, e) in enumerate(queries):
        two_wins = analyze_game(s, e)
