sys.setrecursionlimit(20000)

def solution(input_str):
    lines = input_str.strip().split('\n')
    if not lines:
        return "-1\n"
    n = int(lines[0])

    adj = [lines[i+1] for i in range(1, n+1)]
    target_idx = n + 1
    if target_idx < len(lines):
        targets = list(map(int, lines[target_idx].split()))
    else:
        targets = [0] * n

    def check(mask):
        """Check if mask (bitmask of selected employees) is valid"""
        actual = [0] * n
        for j in range(n):
            if (mask >> j) & 1:  # employee j comes to party
                for i in range(n):
                    if adj[i][j] == '1':  # j has i in contacts
                        actual[i] += 1
        for i in range(n):
            if actual[i] == targets[i]:
                return False  # matches target, invalid
        return True

    # Try subsets using DFS
    def dfs(idx, target_count, current_mask):
        if target_count == 0:
            return current_mask

        for j in range(idx, n):
            new_mask = current_mask | (1 << j)
            if check(new_mask):
                return new_mask

        return None

    # Try different patterns
    # Case 1: Empty subset
    if check(0):
        return f"0\n"

    # Case 2: Single employee
    for i in range(n):
        mask = 1 << i
        if check(mask):
            result = [i + 1]
            return f"1\n{result[0]}\n"

    # Case 3: Two employees
    for i in range(n):
        for j in range(i + 1, n):
            mask = (1 << i) | (1 << j)
            if check(mask):
                result = sorted([i + 1, j + 1])
                return f"2\n{result[0]} {result[1]}\n"

    # Case 4: Randomized search for larger n
    if n > 10:
        attempts = min(2**(n//2 + 3), 100000)
        for _ in range(attempts):
            mask = 0
            for _ in range(n):
                if randrange(100) < 50:
                    mask |= (1 << randrange(n))
            if check(mask):
                result = [p + 1 for p in range(n) if (mask >> p) & 1]
                return f"{len(result)}\n{' '.join(map(str, result))}\n"

    # Case 5: Systematic search for small n (n <= 20)
