def solution(input_str):
    import sys

    # Increase recursion depth for deep trees
    sys.setrecursionlimit(500000)

    # Parse input
    lines = input_str.strip().split('\n')
    if not lines:
        return ""

    n = int(lines[0])

    # Store line data with active status
    # We'll use Li Chao Tree for efficiency
    # Coordinate range: -10^9 to 10^9

    # Track which query-indices (type 1) are currently active
    lines_by_idx = [None] * n  # line[a,b] for type 1 query at index i (0-indexed)
    active_mask = [False] * n  # is query at index i active

    # Li Chao Tree implementation
    # Using a recursive structure with node caching

    class Line:
        def __init__(self, a, b):
            self.a = a
            self.b = b

        def __repr__(self):
            return f"Line({self.a}, {self.b})"

        def eval(self, x):
            return self.a * x + self.b

    class LiChaoTree:
        def __init__(self, min_q, max_q):
            self.min_q = min_q
            self.max_q = max_q
            self.nodes_a = [0] * (1600000)  # Enough for tree depth ~22
            self.nodes_b = [0] * (1600000)
            self.has_line = [False] * (1600000)

        def _eval(self, node, x):
            if not self.has_line[node]:
                return float('-inf')
            return self.nodes_a[node] * x + self.nodes_b[node]

