def solution(input_str):
    input_lines = input_str.strip().split('\n')
    if not input_lines:
        return ""
    n = int(input_lines[0])

    class Line:
        def __init__(self, a, b):
            self.a, self.b = a, b
        def eval(self, x):
            return self.a * x + self.b

    class LiChaoTree:
        __slots__ = ('min_q', 'max_q', 'tree_a', 'tree_b', 'tree_has')

        def __init__(self, min_q, max_q):
            self.min_q, self.max_q = min_q, max_q
            # Using dictionary for sparse storage
            self.tree_a, self.tree_b, self.tree_has = {}, {}, {}

        def _eval(self, node, x):
            return self.tree_a.get(node) * x + self.tree_b.get(node) if node in self.tree_has else float('-inf')

        def add_line(self, line):
            def add_recursive(node, lq, rq):
                if lq > rq:
                    return
                mid = (lq + rq) >> 1

                if node not in self.tree_has:
                    self.tree_has[node] = True
                    self.tree_a[node], self.tree_b[node] = line.a, line.b
                    return

                # Check if new line is better at midpoint
                if line.eval(mid) > self._eval(node, mid):
                    self.tree_a[node], self.tree_b[node], line = line.a, line.b, Line(*self.tree_a[node], *self.tree_b[node])

                if lq == rq:
                    return

                # Check endpoints
                if line.eval(lq) > self._eval(node, lq):
                    add_recursive(node << 1, lq, mid)
                elif line.eval(rq) > self._eval(node, rq):
                    add_recursive((node << 1) | 1, mid + 1, rq)

            add_recursive(1, self.min_q, self.max_q)

        def query(self, x):
            def query(node, lq, rq):
                if node not in self.tree_has:
                    return float('-inf')
                r = self._eval(node, x)

                if lq == rq:
                    return r

                mid = (lq + rq) >> 1
                if x <= mid:
                    return max(r, query(node << 1, lq, mid))
                else:
                    return max(r, query((node << 1) | 1, mid + 1, rq))

            return query(1, self.min_q, self.max_q)

    tree = LiChaoTree(-1000000000, 1000000000)
    results = []

    # Store to handle deletions
    pair_by_query = {}
    active = set()

    for i in range(n):
        t = int(input_lines[i].split()[0])
        params = list(map(int, input_lines[i].split()))

        if t == 1:
            a, b = params[1], params[2]
            pair_by_query[i] = (a, b)
            tree.add_line(Line(a, b))
        elif t == 2:
            idx = params[1] - 1
            a, b = pair_by_query[idx]
            pair_by_query[idx] = (None, None)
        elif t == 3:
            q = params[1]
            val = tree.query(q)
            if val == float('-inf'):
                results.append("EMPTY SET")
            else:
                results.append(str(int(val)))

    return '\n'.join(results)
